package egsha256x_test

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"os"
	"strings"
	"testing"

	"github.com/egdaemon/eg/runtime/x/wasi/egsha256x"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestDigestIO(t *testing.T) {
	t.Run("hashes the contents of the reader", func(t *testing.T) {
		h := egsha256x.DigestIO(strings.NewReader("hello world"))
		require.NotNil(t, h)
		sum := sha256.Sum256([]byte("hello world"))
		require.Equal(t, hex.EncodeToString(sum[:]), egsha256x.FormatHex(h))
	})

	t.Run("hashes empty reader", func(t *testing.T) {
		h := egsha256x.DigestIO(strings.NewReader(""))
		require.NotNil(t, h)
		sum := sha256.Sum256(nil)
		require.Equal(t, hex.EncodeToString(sum[:]), egsha256x.FormatHex(h))
	})

	t.Run("hashes data larger than the internal buffer", func(t *testing.T) {
		data := bytes.Repeat([]byte("x"), 32*1024)
		h := egsha256x.DigestIO(bytes.NewReader(data))
		require.NotNil(t, h)
		sum := sha256.Sum256(data)
		require.Equal(t, hex.EncodeToString(sum[:]), egsha256x.FormatHex(h))
	})

	t.Run("returns nil on reader error", func(t *testing.T) {
		f, err := os.CreateTemp(t.TempDir(), "")
		require.NoError(t, err)
		require.NoError(t, f.Close())
		h := egsha256x.DigestIO(f)
		require.Nil(t, h)
	})
}
